// Definition for singly-linked list.
struct Node {
    int data;
    struct Node *next;
};

// Function to print the linked list
void printList(struct Node *node) {
    while (node != NULL) {
        printf("%d -> ", node->data);
        node = node->next;
    }
    printf("\n");
}

// Function to separate even and odd nodes
struct Node *divide(struct Node *head) {
    // Result list to hold even nodes
    struct Node *resStart = NULL;
    struct Node *resEnd = NULL;
    // Pointers for the original list
    struct Node *curr = head;
    struct Node *prev = NULL;
    // Move all even nodes from original to result
    while (curr != NULL) {
        // If current node is even
        if (curr->data % 2 == 0) {
            // Remove the current even node from the original list
            if (prev != NULL) {
                prev->next = curr->next;
            } else {
                // If the even node is at the head
                head = curr->next;
            }
            // Add the current even node to the result list
            if (resStart == NULL) {
                resStart = curr;
                resEnd = resStart;
            } else {
                resEnd->next = curr;
                resEnd = resEnd->next;
            }
            curr = curr->next;
        }
        // If the node is odd, just move to the next
        else {
            prev = curr;
            curr = curr->next;
        }
    }
    // If there are no even nodes, return the original list
    if (resStart == NULL) {
        return head;
    }
    // Append the remaining original list (odd nodes) to the result list
    resEnd->next = head;
    // Return the result list (starting with even nodes)
    return resStart;
}

